<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import ParameterReset from './ParameterReset.vue';
import {featureNumberStep} from '../../shared/numeric-wheel.mjs';
import {makeProfile} from '../../server/profiles.mjs';

import {computed} from 'vue';
import {ChevronDown,FolderOpen} from 'lucide-vue-next';
import {useStudio} from '../store';
const props=defineProps({kind:String,title:String,description:String,profile:Object});const s=useStudio();const cfg=computed(()=>(props.profile||s.p)[props.kind]);
const types={face:'FaceDetailer',hand:'DetailerForEach',upscale:'UltimateSDUpscale'};
const names={guide_size:'修复区域尺寸',guide_size_for:'按检测框尺寸计算',max_size:'最大区域尺寸',steps:'采样步数',cfg:'提示词强度 CFG',sampler_name:'采样器',scheduler:'调度器',denoise:'重绘强度',feather:'边缘羽化',noise_mask:'使用噪声遮罩',force_inpaint:'强制区域重绘',bbox_threshold:'检测置信度',bbox_dilation:'检测区域扩张',bbox_crop_factor:'检测裁切倍率',sam_detection_hint:'SAM 检测提示',sam_dilation:'SAM 扩张',sam_threshold:'SAM 阈值',sam_bbox_expansion:'SAM 检测框扩张',sam_mask_hint_threshold:'SAM 遮罩阈值',sam_mask_hint_use_negative:'SAM 负向遮罩提示',drop_size:'忽略小区域',wildcard:'附加提示词',cycle:'修复循环次数',inpaint_model:'使用专用重绘模型',noise_mask_feather:'噪声遮罩羽化',tiled_encode:'分块编码',tiled_decode:'分块解码',upscale_by:'放大倍率',mode_type:'分块模式',tile_width:'分块宽度',tile_height:'分块高度',mask_blur:'遮罩模糊',tile_padding:'分块扩边',seam_fix_mode:'接缝修复模式',seam_fix_denoise:'接缝重绘强度',seam_fix_width:'接缝修复宽度',seam_fix_mask_blur:'接缝遮罩模糊',seam_fix_padding:'接缝扩边',force_uniform_tiles:'统一分块大小',batch_size:'分块批次数'};
const defaultCfg=computed(()=>({...Object.fromEntries(fields.value.map(f=>[f.key,f.default??f.options?.[0]])),...makeProfile((props.profile||s.p).type)[props.kind]}));
function restoreGroup(){Object.assign(cfg.value,JSON.parse(JSON.stringify(defaultCfg.value)));s.notify('已恢复'+props.title+'默认参数');}
const excluded=['enabled','detector','upscale_model','seed','image','model','clip','vae','positive','negative','bbox_detector','segs'];
const fields=computed(()=>{
 const schema=s.schemas[types[props.kind]]?.input||{};const defs={...schema.required,...schema.optional};
 const keys=[...new Set([...Object.keys(cfg.value),...Object.keys(defs).filter(k=>['INT','FLOAT','BOOLEAN','STRING'].includes(defs[k]?.[0])||Array.isArray(defs[k]?.[0]))])].filter(k=>!excluded.includes(k)&&!k.startsWith('detector_'));
 return keys.map(key=>{const def=defs[key];return {key,label:s.t(names[key]||key,key.replaceAll('_',' ')),type:Array.isArray(def?.[0])?'select':typeof cfg.value[key]==='boolean'?'boolean':typeof cfg.value[key]==='number'?'number':def?.[0]==='INT'||def?.[0]==='FLOAT'?'number':'text',options:Array.isArray(def?.[0])?def[0]:key==='sampler_name'?s.models.samplers:key==='scheduler'?s.models.schedulers:key==='mode_type'?['Linear','Chess','None']:key==='seam_fix_mode'?['None','Band Pass','Half Tile','Half Tile + Intersections']:null,min:def?.[1]?.min,max:def?.[1]?.max,step:featureNumberStep(key,def?.[0]),wheelStep:featureNumberStep(key,def?.[0]),default:def?.[1]?.default};});
});
function set(key,value){cfg.value[key]=value;}
</script>
<template><details class="feature-card"><summary><label class="inline-check" @click.stop><input type="checkbox" v-model="cfg.enabled"/>{{ui(title)}}</label><span>{{ui(description)}}</span><span :class="['feature-state',{on:cfg.enabled}]">{{ui(cfg.enabled?s.t('已启用','Enabled'):s.t('未启用','Off'))}}</span><ChevronDown :size="16"/></summary><div class="feature-body"><button class="secondary parameter-group-reset" @click="restoreGroup">{{ui("恢复本组默认参数")}}</button><p class="info-note">{{ui(s.t('这些参数分别继承原版 / 2.9B 工作流。启用后接在生成流程之后执行。','Settings match the selected model workflow. Runs after generation when enabled.'))}}</p><div class="field-row"><div class="resettable-field" ><label><span class="parameter-caption">{{ui(kind==='upscale'?s.t('放大模型','Upscale model'):s.t('检测模型','Detection model'))}}</span><select v-if="kind==='upscale'" v-model="cfg.upscale_model"><option :value="cfg.upscale_model">{{ui(cfg.upscale_model)}}</option><option v-for="m in s.models.upscale_models" :value="m">{{ui(m)}}</option></select><select v-else v-model="cfg.detector"><option :value="cfg.detector">{{ui(cfg.detector)}}</option><option v-for="m in s.models.detectors" :value="m">{{ui(m)}}</option></select></label><ParameterReset :model="cfg" :defaults="defaultCfg" :path="kind==='upscale'?'upscale_model':'detector'"/></div><button class="secondary" @click="s.openFolder(kind==='upscale'?'upscale_models':'detectors')"><FolderOpen :size="15"/>{{ui(s.t('打开模型目录','Open model folder'))}}</button></div><div class="parameter-grid"><div class="resettable-field" v-for="f in fields" :key="f.key"><label   :class="{checkbox:f.type==='boolean'}"><span class="parameter-caption">{{ui(f.label)}}</span><select v-if="f.options" :value="cfg[f.key]??f.default??f.options[0]" @change="set(f.key,$event.target.value)"><option v-for="o in f.options" :value="o">{{ui(o)}}</option></select><input v-else-if="f.type==='boolean'" type="checkbox" :checked="cfg[f.key]??f.default" @change="set(f.key,$event.target.checked)"/><input v-else-if="f.type==='number'" type="number" :value="cfg[f.key]??f.default" :min="f.min" :max="f.max" :step="f.step" :data-wheel-step="f.wheelStep" :data-wheel-integer="f.step===1?'':null" @change="set(f.key,Number($event.target.value))"/><input v-else :value="cfg[f.key]??f.default??''" @change="set(f.key,$event.target.value)"/></label><ParameterReset :model="cfg" :defaults="defaultCfg" :path="f.key" :label="ui(f.label)"/></div></div><div v-if="kind==='hand'" class="parameter-grid"><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('手部检测置信度','Detection threshold'))}}</span><input type="number" v-model.number="cfg.detector_threshold" min="0" max="1" step="0.01"/></label><ParameterReset :model="cfg" :defaults="defaultCfg" path="detector_threshold"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('检测区域扩张','Region dilation'))}}</span><input type="number" v-model.number="cfg.detector_dilation"/></label><ParameterReset :model="cfg" :defaults="defaultCfg" path="detector_dilation"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('检测裁切倍率','Crop factor'))}}</span><input type="number" v-model.number="cfg.detector_crop_factor" step="0.1"/></label><ParameterReset :model="cfg" :defaults="defaultCfg" path="detector_crop_factor"/></div><div class="resettable-field" ><label><span class="parameter-caption">{{ui(s.t('忽略小区域','Minimum region'))}}</span><input type="number" v-model.number="cfg.detector_drop_size"/></label><ParameterReset :model="cfg" :defaults="defaultCfg" path="detector_drop_size"/></div></div></div></details></template>
